function updateChapterNavigation(id){
const index=chapters.findIndex(c=>c.id===id),bar=document.querySelector('#chapter-bar');
bar.innerHTML=`<button class="btn chapter-prev" ${index<=0?'disabled':''} aria-label="이전 챕터">← <span>이전</span></button><label class="chapter-picker"><span class="sr-only">챕터 바로 이동</span><select id="chapter-select">${chapters.map((c,i)=>`<option value="${c.id}" ${c.id===id?'selected':''}>${String(i+1).padStart(2,'0')} / ${chapters.length} · ${c.title}</option>`).join('')}</select></label><button class="btn chapter-next" ${index===chapters.length-1?'disabled':''} aria-label="다음 챕터"><span>다음</span> →</button><button class="btn chapter-all">전체 목차</button>`;
bar.querySelector('.chapter-prev').onclick=()=>{if(index>0)location.hash=chapters[index-1].id;};bar.querySelector('.chapter-next').onclick=()=>{if(index<chapters.length-1)location.hash=chapters[index+1].id;};bar.querySelector('#chapter-select').onchange=e=>{location.hash=e.target.value;};bar.querySelector('.chapter-all').onclick=openChapterMenu;
const d=document.querySelector('#chapter-dialog');if(d.open){if(d.close)d.close();else d.removeAttribute('open');}
}
function openChapterMenu(){const d=document.querySelector('#chapter-dialog'),s=document.querySelector('#toc-search'),list=document.querySelector('#toc-list');const draw=()=>{const q=s.value.trim().toLowerCase();list.innerHTML=chapters.map((c,i)=>({...c,n:i+1})).filter(c=>(c.title+' '+c.desc+' '+c.section).toLowerCase().includes(q)).map(c=>`<a href="#${c.id}" ${location.hash==='#'+c.id?'aria-current="page"':''}><b>${String(c.n).padStart(2,'0')} · ${c.title}</b><span>${c.desc}</span></a>`).join('')||'<p>일치하는 챕터가 없습니다.</p>';list.querySelectorAll('a').forEach(a=>a.onclick=()=>{if(d.close)d.close();else d.removeAttribute('open');});};s.value='';s.oninput=draw;draw();document.querySelector('#toc-close').onclick=()=>{if(d.close)d.close();else d.removeAttribute('open');};d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom){if(d.close)d.close();else d.removeAttribute('open');}}};if(d.showModal)d.showModal();else d.setAttribute('open','');}
